// The service description (PWS v0.5 discovery): what this server speaks and
// where its Spaces Repository is. Served at GET /service, the place the
// reference client (pws-client 0.105+) and FreeWallet read it from under a
// base server URL, and still at GET / for clients that follow the `Link`
// header from the root; written verbatim into every Space archive the
// export operation produces, so one builder.

export const SPEC_ID = "https://w3id.org/pws";
export const SPEC_VERSION = "0.5";
export const SPEC_URL = "https://w3c-ccg.github.io/portable-web-spaces-spec/";

// The companion specifications this server lists entries under.
export const EC_SPEC_ID = "https://w3id.org/pws/encrypted-collections";
export const EC_SPEC_URL = "https://w3c-ccg.github.io/portable-web-spaces-spec/ec/";
export const AUTHZ_SPEC_ID = "https://w3id.org/pws/authz-profile";
export const AUTHZ_SPEC_URL = "https://w3c-ccg.github.io/portable-web-spaces-spec/authz-profile/";
// The client-annex clause (the reference server's bound on what a
// delegation-only "ladder" verification method may delegate, enforced by
// the authorizer's chain inspector): a conformance claim a wallet checks
// at signup, with nothing further to advertise, so the entry carries
// `version` alone.
export const CLIENT_ANNEX_ID = "https://w3id.org/pws/client-annex";
export const CLIENT_ANNEX_VERSION = "0.1";

// The feature tokens of the spec's conformance profile table, spelled as
// the table lists them; a client ignores tokens it does not know. The
// Spaces Repository is advertised by the `spaces` URL, not a token;
// conditional requests are baseline. `metadata` is the Resource Metadata
// object, `policy` the access-control policies, `export` the Export and
// Import Space operations together, `encryption` the server-side
// validation of `edv` descriptors (epochs.mjs).
export const FEATURES = [
  "listing",
  "collection-management",
  "space-management",
  "metadata",
  "policy",
  "export",
  "encryption",
  "changes-query",
  "created-by",
];

// PWS-EC's tokens: `governed-history-logs` for the meta/log sub-resource
// and the descriptor derived from it (history.mjs).
export const EC_FEATURES = ["governed-history-logs"];

// The store's origin id: the origin half of a write stamp, advertised on
// the core version entry so a replica can tell this store's stamps from
// another's. Set per deployment (`ORIGIN_ID`); stable for the store's life.
export const originId = () => process.env.ORIGIN_ID ?? "dcc-was-sandbox";

export function serviceDescription(req) {
  return {
    url: `${req.base}/service`,
    specs: {
      [SPEC_ID]: [
        {
          version: SPEC_VERSION,
          url: SPEC_URL,
          spaces: `${req.base}/spaces/`,
          features: FEATURES,
          originId: originId(),
        },
      ],
      [AUTHZ_SPEC_ID]: [
        {
          version: "0.1",
          url: AUTHZ_SPEC_URL,
          signatureAlgorithms: ["EdDSA"],
          zcapCryptosuites: ["eddsa-jcs-2022", "Ed25519Signature2020"],
        },
      ],
      [EC_SPEC_ID]: [
        {
          version: "0.1",
          url: EC_SPEC_URL,
          features: EC_FEATURES,
        },
      ],
      [CLIENT_ANNEX_ID]: [{ version: CLIENT_ANNEX_VERSION }],
    },
    instance: {
      name: "was-server-aws",
      version: process.env.INSTANCE_VERSION ?? "0.0.0",
      source: "https://github.com/digitalcredentials/was-server-aws",
    },
  };
}
